const HYDERABAD_BY_SLUG = new Map();
const HYDERABAD_BY_ID = new Map();
HYDERABAD_REGISTRY_PROJECTS.forEach((p) => {
  HYDERABAD_BY_SLUG.set(p.slug, p);
  HYDERABAD_BY_ID.set(String(p.id), p);
  const shortSlug = p.slug.replace(/-pid-\d+$/, "");
  if (!HYDERABAD_BY_SLUG.has(shortSlug)) {
    HYDERABAD_BY_SLUG.set(shortSlug, p);
  }
});

// Specific backward-compatibility aliases
if (HYDERABAD_BY_ID.has("8379")) {
  HYDERABAD_BY_SLUG.set("my-home-sayuk", HYDERABAD_BY_ID.get("8379"));
}
if (HYDERABAD_BY_ID.has("8340")) {
  HYDERABAD_BY_SLUG.set("aparna-zenon", HYDERABAD_BY_ID.get("8340"));
}

export const HYDERABAD_ALL_SLUGS = HYDERABAD_REGISTRY_PROJECTS.map((p) => p.slug);

export const HYDERABAD_PROJECT_COORDINATES = {};
HYDERABAD_REGISTRY_PROJECTS.forEach((p) => {
  if (typeof p.lat === "number" && typeof p.lng === "number") {
    HYDERABAD_PROJECT_COORDINATES[p.slug] = {
      lat: p.lat,
      lng: p.lng,
      locality: p.location,
      city: "hyderabad",
      cityName: "Hyderabad",
      propertyType: p.type || "Apartment",
      verified: true,
    };
    HYDERABAD_PROJECT_COORDINATES[p.id] = HYDERABAD_PROJECT_COORDINATES[p.slug];
    const shortSlug = p.slug.replace(/-pid-\d+$/, "");
    HYDERABAD_PROJECT_COORDINATES[shortSlug] = HYDERABAD_PROJECT_COORDINATES[p.slug];
  }
});
if (HYDERABAD_PROJECT_COORDINATES["8379"]) {
  HYDERABAD_PROJECT_COORDINATES["my-home-sayuk"] = HYDERABAD_PROJECT_COORDINATES["8379"];
}
if (HYDERABAD_PROJECT_COORDINATES["8340"]) {
  HYDERABAD_PROJECT_COORDINATES["aparna-zenon"] = HYDERABAD_PROJECT_COORDINATES["8340"];
}

function buildAmenitiesForHyderabad(features = []) {
  return (features || []).map((feat) => {
    const fLower = String(feat).toLowerCase();
    let cat = "Lifestyle";
    let icon = "Sparkles";
    if (fLower.includes("pool") || fLower.includes("gym") || fLower.includes("fitness") || fLower.includes("yoga") || fLower.includes("jogging") || fLower.includes("spa")) {
      cat = "Wellness"; icon = "Dumbbell";
    } else if (fLower.includes("security") || fLower.includes("cctv") || fLower.includes("intercom") || fLower.includes("gated") || fLower.includes("fire")) {
      cat = "Security"; icon = "Shield";
    } else if (fLower.includes("club") || fLower.includes("hall") || fLower.includes("theatre") || fLower.includes("lounge") || fLower.includes("party")) {
      cat = "Social"; icon = "Coffee";
    } else if (fLower.includes("garden") || fLower.includes("tree") || fLower.includes("ev") || fLower.includes("rain") || fLower.includes("solar") || fLower.includes("park")) {
      cat = "Eco"; icon = "Zap";
    } else if (fLower.includes("court") || fLower.includes("sport") || fLower.includes("track") || fLower.includes("cricket") || fLower.includes("badminton")) {
      cat = "Sports"; icon = "Trophy";
    }
    return { name: feat, category: cat, icon };
  });
}

function buildConfigurationsForHyderabadProject(p) {
  const plans = [];
  const areaVal = p.carpetArea !== "On Request" ? p.carpetArea : (p.builtUpArea || "1,250 - 2,400 sq.ft.");
  const imgUrl = p.images?.[0] || "/images/placeholder-property.jpg";

  plans.push({
    type: p.flatTypes || p.type || "Residential Unit",
    bhk: p.flatTypes || p.type || "2, 3 BHK",
    carpetArea: p.carpetArea || "On Request",
    superArea: p.builtUpArea || areaVal,
    area: areaVal,
    price: p.price && p.price !== "On Request" ? `₹ ${p.price}` : "On Request",
    specs: { bedrooms: 3, bathrooms: 3, balconies: 2, parking: "Covered Parking" },
    facing: "East / North Facing (Vastu Compliant)",
    description: `Spacious, well-ventilated layout at ${p.name}, ${p.location} with premium vitrified tile flooring, modular fittings, and scenic balconies.`,
    propertyType: p.type || "Apartment",
    image: imgUrl,
    layoutImage: imgUrl,
    key: `${p.id}-default`,
  });

  return plans;
}

export function getHyderabadProjectBySlug(rawSlug) {
  if (!rawSlug) return null;
  const clean = decodeURIComponent(String(rawSlug)).toLowerCase().trim();
  let p = HYDERABAD_BY_SLUG.get(clean) || HYDERABAD_BY_ID.get(clean);
  if (!p) {
    const pidMatch = clean.match(/-pid-(\d+)$/) || clean.match(/-(\d+)$/);
    if (pidMatch) p = HYDERABAD_BY_ID.get(pidMatch[1]);
  }
  if (!p) return null;

  const extras = HYDERABAD_REGISTRY_EXTRAS[p.slug] || {};
  const specs = [
    { label: "Configurations", value: p.flatTypes || "On Request" },
    { label: "Carpet Area", value: p.carpetArea || "On Request" },
    { label: "Built-up Area", value: p.builtUpArea || "On Request" },
    { label: "Possession", value: p.possession || "Under Construction" },
    { label: "Project Status", value: p.status || "Under Construction" },
    { label: "Project Area", value: p.projectArea || "On Request" },
    { label: "Average Rate", value: p.avgPrice || "On Request" },
    { label: "TG RERA ID", value: p.rera || "Not Available" },
  ];

  const reraIds = (p.rera_informations && p.rera_informations.length > 0)
    ? p.rera_informations
    : (p.rera && p.rera !== "Not Available"
        ? p.rera.split(",").map((id) => ({ rera_id: id.trim() }))
        : []);

  const sameLocality = HYDERABAD_REGISTRY_PROJECTS.filter((item) => item.locality === p.locality && item.slug !== p.slug);
  const otherHyd = (sameLocality.length >= 3
    ? sameLocality
    : HYDERABAD_REGISTRY_PROJECTS.filter((item) => item.slug !== p.slug)
  ).slice(0, 4);

  const landmarks = [
    { name: `${p.locality} Metro Station / Arterial Connector`, distance: "1.5 km", time: "5 mins", type: "Transit" },
    { name: "Outer Ring Road (ORR) / Rajiv Gandhi International Airport Expressway", distance: "4.0 km", time: "10 mins", type: "Road" },
    { name: "AIG Hospitals / Continental / CARE Hospitals", distance: "3.2 km", time: "8 mins", type: "Healthcare" },
    { name: "Oakridge / Delhi Public School / Chirec International", distance: "2.5 km", time: "7 mins", type: "Education" },
    { name: "Hitec City / Financial District Cyber Towers CBD", distance: "5.5 km", time: "14 mins", type: "Work" },
  ];

  return {
    id: p.id,
    slug: p.slug,
    title: p.name,
    name: p.name,
    builder: p.builder,
    builderLogo: p.builderLogo,
    developerSlug: p.developerSlug,
    city: "hyderabad",
    cityName: "Hyderabad",
    region: p.region,
    locality: p.locality,
    location: p.location,
    fullAddress: p.fullAddress,
    lat: p.lat,
    lng: p.lng,
    price: p.price,
    priceNumeric: p.priceNumeric,
    avgPrice: p.avgPrice,
    flatTypes: p.flatTypes,
    carpetArea: p.carpetArea,
    builtUpArea: p.builtUpArea,
    possession: p.possession,
    status: p.status,
    rera: p.rera,
    reraIds,
    tag: p.tag,
    propertyType: p.type || "Apartment",
    isExclusive: p.isExclusive,
    isTrending: p.isTrending,
    rating: 4.8,
    reviewsCount: 110,
    images: p.images,
    overview: p.description,
    highlights: [
      `Prime address in ${p.location} with immediate transit access`,
      `Master planned community crafted by ${p.builder}`,
      p.rera && p.rera !== "Not Available" ? `TG RERA Approved: ${p.rera}` : "Transparent documentation and RERA compliant",
      `Available Typologies: ${p.flatTypes}`,
      "Contemporary clubhouse, landscape open spaces, and premium lifestyle amenities",
      "Direct builder inventory with zero brokerage through AuraLiving"
    ],
    amenities: buildAmenitiesForHyderabad(p.features),
    specifications: specs,
    floorPlans: buildConfigurationsForHyderabadProject(p),
    landmarks,
    developerInfo: {
      name: p.builder,
      slug: p.developerSlug,
      logo: p.builderLogo || "https://images.unsplash.com/photo-1541888946425-d0fbb186f5f7?auto=format&fit=crop&w=120&h=120&q=80",
      experience: "25+ Years",
      projectsCount: "35+ Projects",
      established: "1998",
      description: p.builderDescription || `${p.builder} is a leading real estate brand in Hyderabad known for architectural excellence and on-time delivery.`
    },
    relatedProjectSlugs: otherHyd.map((x) => x.slug),
  };
}
